/* 内容库的 ID 生成器（与批次 ID 同风格：时间戳 + 随机尾） */
function _libId(){ return 'l' + Date.now().toString(36) + Math.random().toString(36).slice(2,6); }

/* 预置灌底：字段为 null（从未用过）才整表灌入，已有内容一律不动。
   boot() 里 load() 之后必调一次 —— 这样 v2 老用户、v1 迁移用户、首次安装三条路都能拿到预置。 */
function _seedLibraries(){
  if(!Array.isArray(S.navLinks))  S.navLinks  = PRESET_NAV.map(x=>({ id:_libId(), ...x }));
  if(!Array.isArray(S.templates)) S.templates = PRESET_TPL.map(x=>({ id:_libId(), ...x }));
  if(!Array.isArray(S.todos)) S.todos = [];
  // 一次性迁移：v1.3 的工作笔记按行拆成备忘清单项（非空行各成一条），迁移后不再展示原文
  if(!S._notesMigrated && typeof S.notes === 'string' && S.notes.trim()){
    S.notes.split('\n').map(s=>s.trim()).filter(Boolean).forEach(line=>{
      S.todos.push({ id:_libId(), text:line, done:false, created:todayStr() });
    });
    S._notesMigrated = true;
  }
}

/* 「恢复预置」：按名称/标题补回缺失的预置项，只增不改（自定义的内容永远安全） */
function restoreLibraryPresets(key){
  const map = { navLinks:PRESET_NAV, templates:PRESET_TPL };
  const lib = S[key]; const presets = map[key];
  if(!Array.isArray(lib) || !presets) return 0;
  const nameKey = key === 'navLinks' ? 'name' : 'title';
  const have = new Set(lib.map(x=>String(x[nameKey]||'').trim()));
  let n = 0;
  presets.forEach(p=>{
    if(!have.has(String(p[nameKey]||'').trim())){ lib.push({ id:_libId(), ...p }); n++; }
  });
  if(n){ save(); }
  return n;
}
